// one "+ New" item: doc:<type> | eq:<action> | asset:new | asset:depr | entry:<entry type id>
function newItem(key) {
  const [kind, id] = key.includes(":") ? key.split(/:(.*)/s) : ["doc", key];
  if (kind === "doc") return openDoc(id);
  if (kind === "eq") return id === "drawing" ? openDoc("partner_tx") : equityForm(id);
  if (kind === "asset") return id === "depr" ? deprForm() : assetForm();
  if (kind === "entry") return entryTypeForm(id);
  if (kind === "loan") return id === "pay" ? pickThen("loans", lid => loanAction(lid, "pay")) : loanForm();
  if (kind === "contact") return contactForm({}, cid => contactView(cid));
  if (kind === "sale") return id === "collect" ? pickSale(s => collectForm(s)) : saleForm();
  if (kind === "product") return productForm();
  if (kind === "recurring") return recurringForm();
  if (kind === "po") return poForm();
  if (kind === "site") return ({ task: () => taskForm(), contract: () => contractForm({ kind: "client", status: "active", lines: [] }),
    subcontract: () => contractForm({ kind: "sub", status: "active", lines: [] }), prq: () => prForm(),
    usage: async () => { await eqLoad(); usageForm(); }, maint: async () => { await eqLoad(); maintForm(); },
    attendance: () => { location.hash = "#/attendance"; }, ereceipt: () => erForm() })[id]();
  if (kind === "sub") return subForm();
  if (kind === "bank") return bankImportForm();
  if (kind === "custody") return id === "settle" ? pickThen("custody", c => custodyAction(c, "settle")) : custodyForm();
}
async function openDoc(type, pre, edit, copyVals, via) {
  if (type === "invoice") { location.hash = "#/invoice/new"; return; }
  if (type === "offer") { location.hash = "#/offers"; return; }
  if (type === "journal") return journalForm();
  if (type === "bu") return buForm();
  const d = DOCS[type]; if (!d) return;
  let names = [];
  try { names = (await api("GET", "/api/parties?kind=all")).names; } catch { /* no permission */ }
  const items = S.boot.items.map(i => i.name);
  const vals = (via && via.vals) || (edit && edit.form) || copyVals;
  const nc = [];
  drawer(t(d.title) + " — " + (via ? `${L2("Draft", "مسودة")} #${via.aid}` : edit ? `${t("edit")} #${edit.id}` : t("new")), form([...d.fields(pre), ...(via ? [] : [ATTACH_FIELD()])]) + unitsList() + partyList("parties", names) + datalist("items", items),
    async (v, f) => { delete v._files; const r = edit ? await sendEntry("PUT", `/api/docs/${type}/${edit.id}`, v, via, t("saved")) : await sendEntry("POST", "/api/docs/" + type, v, via, t("posted"));
      await attachFrom(f, r, edit && edit.id); await saveNewContacts(nc); },
    { submitLabel: via ? (via.mode === "approve" ? L2("Approve & post", "اعتماد وترحيل") : L2("Send for approval", "إرسال للاعتماد")) : undefined,
      onOpen: f => { if (d.open) d.open(f, !!edit); if (vals) fillForm(f, vals); if (d.calc) { S.H.calc = () => d.calc(f); d.calc(f); }
      [["vendor", "supplier"], ["party", type === "receipt" ? "customer" : "supplier"], ["worker", "employee"]].forEach(([k, c]) => { if ($(`[name=${k}]`, f) && $(`[name=${k}]`, f).getAttribute("list") === "parties") nc.push(offerContact(f, k, c)); }); } });
}
function fillForm(f, vals) {
  Object.entries(vals).forEach(([k, v]) => { const el = $(`[name="${k}"]`, f); if (!el || v == null) return;
    if (el.type === "checkbox") el.checked = v === true || v === 1 || v === "1" || v === "true";
    else if (el.tagName === "SELECT" && ![...el.options].some(o => o.value === String(v))) return;
    else el.value = v; });
}
function journalLinesEditor(lines) {
  const opts = S.boot.accounts.filter(a => a.active).map(a => `<option value="${a.code}">${esc(a.code)} ${esc(aname(a))}</option>`).join("");
  return `<div class="tbl"><table id="jl"><thead><tr><th>${t("account")}</th><th class="num">${t("debit")}</th><th class="num">${t("credit")}</th><th title="${esc(t("line_party_help"))}">${t("line_party")}</th><th></th></tr></thead><tbody>
    ${lines.map(l => `<tr><td><select data-skip="1" class="ja"><option value="">—</option>${opts.replace(`value="${l.account}"`, `value="${l.account}" selected`)}</select></td>
      <td><input data-skip="1" class="jd num" type="number" step="any" value="${l.debit || ""}" data-input="jbal"></td><td><input data-skip="1" class="jc num" type="number" step="any" value="${l.credit || ""}" data-input="jbal"></td>
      <td><input data-skip="1" class="jp" value="${esc(l.party || "")}" list="jparties" style="min-width:90px"></td>
      <td><button type="button" class="btn sm danger" data-a="jrm">✕</button></td></tr>`).join("")}</tbody></table></div>
    ${partyList("jparties", (S.boot.partners || []).map(p => p.name))}
    <div class="row" style="margin-top:8px"><button type="button" class="btn sm" data-a="jadd">${t("add_line")}</button><span class="spacer"></span><span id="jbal"></span></div>`;
}
// item lines on a journal voucher: item (pick or type a new one), unit, qty × unit price = total, and where it goes —
// a warehouse (stock goes up on this same voucher) or straight onto the business unit chosen above
function jItemsEditor(pre) {
  const dest = `<option value="">${esc(L2("Project (above)", "المشروع (أعلاه)"))}</option>` +
    S.boot.warehouses.filter(w => w.active !== 0 && w.active !== false).map(w => `<option value="${w.id}">${esc(L2("Store: ", "مخزن: ") + w.name)}</option>`).join("");
  const row = (x = {}) => `<tr><td><input class="ji-n" list="jitemlist" value="${esc(x.item || "")}" placeholder="${esc(L2("Item or material", "الصنف أو الخامة"))}"></td>
    <td><input class="ji-u" list="units" value="${esc(x.unit || "")}" style="width:62px"></td><td><input class="ji-q" type="number" step="any" value="${esc(x.qty ?? "")}" style="width:70px"></td>
    <td><input class="ji-p" type="number" step="any" value="${esc(x.rate ?? "")}" style="width:90px"></td><td class="num ji-t">—</td>
    <td><select class="ji-w no-pick">${x.warehouse ? dest.replace(`>${esc(L2("Store: ", "مخزن: ") + x.warehouse)}<`, ` selected>${esc(L2("Store: ", "مخزن: ") + x.warehouse)}<`) : dest}</select></td><td><button type="button" class="btn sm" data-a="jirm" aria-label="${esc(t("remove"))}">✕</button></td></tr>`;
  return `<details class="ji-box" ${pre && pre.length ? "open" : ""}><summary><b>${esc(L2("Items & materials", "الأصناف والخامات"))}</b> <span class="muted">${esc(L2("— quantity × unit price; into stock or used on a project. Then enter only who was paid or owed below.", "— الكمية × سعر الوحدة؛ إلى المخزن أو استُخدمت في مشروع. ثم أدخل فقط الطرف الدائن (من دُفع له أو يُستحق له) بالأسفل."))}</span></summary>
    <div class="tbl"><table id="ji"><thead><tr><th>${esc(t("item"))}</th><th>${esc(t("unit"))}</th><th class="num">${esc(L2("Qty", "الكمية"))}</th><th class="num">${esc(L2("Unit price", "سعر الوحدة"))}</th><th class="num">${esc(t("total"))}</th><th>${esc(L2("Goes to", "الوجهة"))}</th><th></th></tr></thead>
    <tbody>${(pre && pre.length ? pre : [{}]).map(row).join("")}</tbody></table></div>
    <div class="row" style="margin-top:6px;gap:8px"><button type="button" class="btn sm" data-a="jiadd">+ ${esc(L2("Item", "صنف"))}</button><span class="muted" id="jitot"></span></div>
    <datalist id="jitemlist"></datalist>${unitsList()}<template id="jirow">${row()}</template></details>`;
}
const jItemsTotal = f => $$("#ji tbody tr", f).reduce((s, tr) => s + (+$(".ji-q", tr).value || 0) * (+$(".ji-p", tr).value || 0), 0);
function jItemsWire(f, bal) {
  let names = [];
  api("GET", "/api/items/names").then(d => { names = d.rows; $("#jitemlist", f).innerHTML = names.map(n => `<option value="${esc(n.name)}">`).join(""); }).catch(() => {});
  const upd = () => { $$("#ji tbody tr", f).forEach(tr => { const v = (+$(".ji-q", tr).value || 0) * (+$(".ji-p", tr).value || 0); $(".ji-t", tr).textContent = v ? money(v) : "—"; });
    const tot = jItemsTotal(f); $("#jitot", f).textContent = tot ? `${L2("Items total", "إجمالي الأصناف")}: ${money(tot)}` : ""; bal(); };
  $("#ji", f).addEventListener("input", e => {
    const tr = e.target.closest("tr");
    if (e.target.classList.contains("ji-n")) { const n = names.find(x => x.name === e.target.value);
      if (n) { if (!$(".ji-u", tr).value) $(".ji-u", tr).value = n.unit; if (!$(".ji-p", tr).value && n.price) $(".ji-p", tr).value = n.price; } }
    upd(); });
  S.H.jiadd = () => { $("#ji tbody", f).insertAdjacentHTML("beforeend", $("#jirow", f).innerHTML); };
  S.H.jirm = el => { const tb = $("#ji tbody", f); if (tb.children.length > 1) el.closest("tr").remove(); else $$("input", el.closest("tr")).forEach(i => { i.value = ""; }); upd(); };
  upd();
}
// Saving an entry. Someone whose entries need approval gets a draft back instead of a posted entry. `via` = working on a
// draft: the approver posts it (changed or not), or its maker fixes it and sends it again.
async function sendEntry(method, path, body, via, okMsg) {
  if (via && via.mode === "approve") { const r = await api("POST", `/api/approvals/${via.aid}/approve`, { payload: body }); toast(L2("Approved and posted", "تم الاعتماد والترحيل")); loadAlerts(true); return r; }
  if (via) { await api("PUT", `/api/approvals/${via.aid}`, { payload: body }); toast(L2("Changed — waiting for approval again", "تم التعديل — في انتظار الاعتماد مرة أخرى")); loadAlerts(true); return {}; }
  const r = await api(method, path, body);
  if (r && r.pending) { toast(L2(`Saved as draft #${r.approval} — it is posted once someone approves it`, `حُفظ كمسودة رقم ${r.approval} — يُرحّل بعد اعتماده`)); loadAlerts(true); }
  else toast(okMsg);
  return r;
}
