      const over = {}; $$("#rcsvc [data-ov]").forEach(x => { const [c, k] = x.dataset.ov.split(":"); (over[c] = over[c] || {})[k] = x.value; });
      if (sv && !sv.transport) { over.transport_out = { off: true }; over.transport_back = { off: true }; }
