const C_ST = { pending: ["Under collection", "تحت التحصيل", "warn"], cleared: ["Cleared", "تم الصرف", "ok"], bounced: ["Bounced", "مرتد", "bad"] };
const PLAN_T = () => [["full", L2("Paid in full", "كاش / دفعة واحدة")], ["deferred", L2("Deferred (one later payment)", "آجل (دفعة واحدة لاحقاً)")], ["installments", L2("Installments", "تقسيط")], ["custom", L2("Custom schedule", "جدول مخصص")]];
const FREQS = () => [["monthly", L2("Monthly", "شهري")], ["quarterly", L2("Quarterly", "ربع سنوي")], ["semiannual", L2("Every 6 months", "نصف سنوي")], ["annual", L2("Yearly", "سنوي")]];
const instLabel = r => { if (S.lang !== "ar") return r.label || r.kind;
  if (r.kind === "installment" && /\d+\/\d+/.test(r.label || "")) return `قسط ${(r.label.match(/\d+\/\d+/) || [""])[0]}`;
  if (r.kind === "down") return r.label === "Full payment" ? "دفعة كاملة" : "مقدم"; if (r.kind === "balance") return "دفعة";
  return r.label && r.label !== "Extra payment" ? r.label : "دفعة إضافية"; };
const pname = p => (S.lang === "ar" && p.name_ar ? p.name_ar : p.name);
const SPEC_PRESETS = { unit: [["Area", "المساحة"], ["Floor", "الدور"], ["Bedrooms", "غرف النوم"], ["Bathrooms", "الحمامات"], ["View", "الإطلالة"], ["Finishing", "التشطيب"], ["Delivery", "الاستلام"]],
  item: [["Brand", "الماركة"], ["Model", "الموديل"], ["Size", "المقاس"], ["Colour", "اللون"], ["Material", "الخامة"], ["Warranty", "الضمان"]], service: [["Duration", "المدة"], ["Includes", "يشمل"]] };

// --- media helpers: uploaded files travel as data URLs; players for links
const dataToBlobUrl = (dataUrl) => { const m = /^data:([^;]*);base64,(.*)$/s.exec(dataUrl || ""); if (!m) return dataUrl;
  const bin = atob(m[2]), u = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i);
  return URL.createObjectURL(new Blob([u], { type: m[1] || "application/octet-stream" })); };
let mvLoading = null;
const loadModelViewer = () => mvLoading || (mvLoading = new Promise((res, rej) => { if (customElements.get("model-viewer")) return res();
  const sc = document.createElement("script"); sc.src = "vendor/model-viewer-4.3.1.min.js"; sc.onload = () => res(); sc.onerror = () => { mvLoading = null; rej(new Error("3D viewer could not load")); }; document.head.appendChild(sc); }));
function embedUrl(url) {
  let m;
  if ((m = /(?:youtube\.com\/(?:watch\?(?:.*&)?v=|shorts\/|embed\/)|youtu\.be\/)([\w-]{6,})/i.exec(url))) return { frame: `https://www.youtube-nocookie.com/embed/${m[1]}?rel=0` };
  if ((m = /vimeo\.com\/(?:video\/)?(\d+)/i.exec(url))) return { frame: `https://player.vimeo.com/video/${m[1]}` };
  if ((m = /drive\.google\.com\/file\/d\/([\w-]+)/i.exec(url))) return { frame: `https://drive.google.com/file/d/${m[1]}/preview` };
  if ((m = /sketchfab\.com\/(?:3d-models\/[^/?#]*-|models\/)([0-9a-f]{32})/i.exec(url))) return { frame: `https://sketchfab.com/models/${m[1]}/embed?autostart=1` };
  if (/\.(glb|gltf)(\?|#|$)/i.test(url)) return { model: url };
  if (/\.(mp4|webm|ogg|mov)(\?|#|$)/i.test(url)) return { video: url };
  if (/\.(jpe?g|png|webp|gif|avif)(\?|#|$)/i.test(url)) return { img: url };
  return { frame: url };
}
async function mediaStage(box, m) {
  box.innerHTML = `<div class="empty">${t("loading")}</div>`;
  try {
    let src = m.url, kind = m.kind;
    if (m.uploaded) { const f = await api("GET", "/api/product-media/" + m.id); src = f.data; }
    let e = m.uploaded ? null : embedUrl(src);
    const isModel = kind === "model" && (m.uploaded || (e && e.model));
    if (kind === "photo" && (m.uploaded || (e && e.img))) box.innerHTML = `<img src="${esc(src)}" alt="${esc(m.title || "")}">`;
    else if (kind === "video" && m.uploaded) box.innerHTML = `<video src="${esc(dataToBlobUrl(src))}" controls playsinline preload="metadata"></video>`;
    else if (isModel) {
      await loadModelViewer();
      const u = m.uploaded ? dataToBlobUrl(src) : e.model;
      box.innerHTML = `<model-viewer src="${esc(u)}" camera-controls touch-action="pan-y" auto-rotate shadow-intensity="1" ar exposure="1" alt="${esc(m.title || "3D")}"></model-viewer>`;
    } else if (e && e.video) box.innerHTML = `<video src="${esc(e.video)}" controls playsinline preload="metadata"></video>`;
    else if (e && e.img) box.innerHTML = `<img src="${esc(e.img)}" alt="">`;
    else if (e && e.frame) box.innerHTML = `<iframe src="${esc(e.frame)}" allow="autoplay; fullscreen; xr-spatial-tracking; accelerometer; gyroscope" allowfullscreen loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe>`;
    else box.innerHTML = `<a class="btn" href="${esc(src)}" download>${esc(m.title || L2("Download", "تحميل"))}</a>`;
  } catch (err) { box.innerHTML = `<div class="banner err">${esc(err.message)}</div>`; }
}
const MEDIA_ICON = { photo: "📷", video: "🎬", model: "🧊", tour: "🌐", file: "📄" };
const mediaThumb = (m, on) => `<button type="button" class="mthumb${on ? " on" : ""}" data-a="pmsel" data-id="${m.id}" title="${esc(m.title || m.kind)}">${m.thumb || (m.kind === "photo" && !m.uploaded && m.url) ? `<img src="${esc(m.thumb || m.url)}" alt="">` : `<span>${MEDIA_ICON[m.kind] || "•"}</span>`}</button>`;
// shrink photos before upload (they sync to every device): long side 1600 px + a 360 px thumbnail
function shrinkImage(file, max, q) {
  return new Promise((res, rej) => { const img = new Image(), u = URL.createObjectURL(file);
    img.onload = () => { const r = Math.min(1, max / Math.max(img.width, img.height)), c = document.createElement("canvas");
      c.width = Math.round(img.width * r); c.height = Math.round(img.height * r); c.getContext("2d").drawImage(img, 0, 0, c.width, c.height);
      URL.revokeObjectURL(u); res(c.toDataURL("image/jpeg", q)); };
    img.onerror = () => { URL.revokeObjectURL(u); rej(new Error(L2("Not an image this browser can read", "صيغة صورة غير مدعومة"))); }; img.src = u; });
}
// -------------------------------------------------------------- attachments
// <div class="attbox" data-owner="entry" data-id="12" data-edit="1"></div> then mountAttach(el): list, add files / photos / links
const attBox = (owner, id, edit) => `<div class="attbox" data-owner="${owner}" data-id="${id}" data-edit="${edit ? 1 : ""}"><h4 class="fsec">📎 ${L2("Attached files", "المرفقات")}</h4><div class="muted">…</div></div>`;
const fileIcon = m => /pdf/.test(m) ? "📕" : /image/.test(m) ? "🖼" : /sheet|excel|csv/.test(m) ? "📊" : /word|document/.test(m) ? "📝" : "📄";
const kb = n => n >= 1048576 ? (n / 1048576).toFixed(1) + " MB" : Math.max(1, Math.round(n / 1024)) + " KB";
async function attFile(id) {
  const r = await api("GET", `/api/attachments/${id}?format=json`);
  if (r.url) return { url: r.url };
  const bin = atob(r.data.split(",")[1]), u8 = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
  return { blob: URL.createObjectURL(new Blob([u8], { type: r.mime || "application/octet-stream" })), title: r.title, mime: r.mime };
}
async function mountAttach(box) {
  if (!box) return;
  const { owner, id } = box.dataset, edit = !!box.dataset.edit;
  let d;
  try { d = await api("GET", "/api/attachments?" + qs({ owner, id })); } catch (e) { box.remove(); return; }
  const rows = d.rows;
  box.innerHTML = `<h4 class="fsec">📎 ${L2("Attached files", "المرفقات")}${rows.length ? ` <span class="chip">${rows.length}</span>` : ""}</h4>
    ${rows.length ? `<div class="attlist">${rows.map(a => `<div class="att" data-id="${a.id}">
      <button type="button" class="attthumb" data-k="open" title="${esc(L2("Open", "فتح"))}">${a.thumb ? `<img src="${esc(a.thumb)}" alt="">` : `<span>${a.url ? "🔗" : fileIcon(a.mime)}</span>`}</button>
      <div class="attmeta"><b dir="auto">${esc(a.title)}</b><span class="muted">${a.url ? L2("link", "رابط") : kb(a.size)} · ${fd((a.created_at || "").slice(0, 10))}${a.created_by ? " · " + esc(a.created_by) : ""}</span></div>
      <div class="attbtns"><button type="button" class="btn sm" data-k="open">${L2("Open", "فتح")}</button>${a.url ? "" : `<button type="button" class="btn sm" data-k="dl">⬇</button>`}
      ${edit ? `<button type="button" class="btn sm" data-k="ren" title="${esc(L2("Rename", "إعادة تسمية"))}">✎</button><button type="button" class="btn sm danger" data-k="del" title="${esc(t("delete"))}">✕</button>` : ""}</div></div>`).join("")}</div>`
      : `<div class="muted" style="font-size:.88em">${L2("No files yet — attach the supplier's invoice, a receipt photo, a signed contract…", "لا توجد ملفات — أرفق فاتورة المورد أو صورة الإيصال أو العقد الموقّع…")}</div>`}
    ${edit ? `<div class="row attadd" style="gap:6px;flex-wrap:wrap;margin-top:8px">
      <label class="btn sm">＋ ${L2("Add files", "إضافة ملفات")}<input type="file" multiple hidden data-k="files"></label>
      <label class="btn sm">📷 ${L2("Take a photo", "التقاط صورة")}<input type="file" accept="image/*" capture="environment" hidden data-k="files"></label>
      <button type="button" class="btn sm" data-k="link">🔗 ${L2("Add a link", "إضافة رابط")}</button>
      <span class="muted" style="font-size:.8em">${L2(`Or drag files here / paste them (Ctrl+V). Up to ${d.max_mb} MB each; photos are shrunk automatically.`, `أو اسحب الملفات هنا / الصقها (Ctrl+V). حتى ${d.max_mb} ميجا للملف؛ الصور تُصغّر تلقائياً.`)}</span></div><div class="attprog muted" style="font-size:.85em"></div>` : ""}`;
  const reload = () => mountAttach(box);
  box.onclick = async ev => {
    const b = ev.target.closest("[data-k]"); if (!b || b.tagName === "INPUT") return;
    const k = b.dataset.k, row = b.closest(".att"), aid = row && row.dataset.id, a = row && rows.find(x => String(x.id) === aid);
    ev.preventDefault(); ev.stopPropagation();
    try {
      if (k === "open") { const f = await attFile(aid); window.open(f.url || f.blob, "_blank", "noopener"); }
      else if (k === "dl") { const f = await attFile(aid); const l = document.createElement("a"); l.href = f.blob; l.download = a.title; document.body.appendChild(l); l.click(); l.remove(); }
      else if (k === "ren") { const n = await uiPrompt(L2("File name", "اسم الملف"), a.title); if (!n) return; await api("PUT", "/api/attachments/" + aid, { title: n }); reload(); }
      else if (k === "del") { if (!await uiConfirm(L2(`Remove “${a.title}”?`, `حذف «${a.title}»؟`))) return; await api("DELETE", "/api/attachments/" + aid); reload(); }
      else if (k === "link") { const u = await uiPrompt(L2("Paste the link (Google Drive, Dropbox, OneDrive…)", "الصق الرابط (جوجل درايف، دروب بوكس…)")); if (!u) return;
        const n = await uiPrompt(L2("Name", "الاسم"), u.replace(/^https?:\/\//, "").slice(0, 60)); await api("POST", "/api/attachments", { owner, id, url: u.trim(), title: n || "" }); reload(); }
    } catch (e) { fail(e); }
  };
  const upload = async files => { const prog = $(".attprog", box); let done = 0; if (!prog || !files.length) return;
    for (const f of files) {
      prog.textContent = `${L2("Uploading", "جارٍ الرفع")} ${f.name || L2("pasted picture", "صورة ملصقة")}… (${done + 1}/${files.length})`;
      try { await uploadFile(owner, id, f); done++; } catch (e) { fail(e); }
    }
    prog.textContent = ""; reload(); };
  $$("input[data-k=files]", box).forEach(inp => inp.onchange = () => upload([...inp.files]));
  if (edit) { box.classList.add("attbox"); if (!box._dzPaste) dropTarget(box, upload); box._dzPaste = upload; }
}
const readDataUrl = file => new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = () => rej(r.error); r.readAsDataURL(file); });
const MAX_UP = 8 * 1024 * 1024;
// one file onto a record (photos shrunk, with a small preview)
async function uploadFile(owner, id, f) {
  let data, thumb = "", mime = f.type, name = f.name;
  if (/^image\/(jpeg|png|webp|heic|heif)/i.test(f.type) || (/^image\//.test(f.type) && f.size > 1.5 * 1048576)) {
    try { data = await shrinkImage(f, 2000, 0.85); mime = "image/jpeg"; if (!/\.jpe?g$/i.test(name)) name = name.replace(/\.\w+$/, "") + ".jpg"; } catch { data = await readDataUrl(f); }
  } else data = await readDataUrl(f);
  if (/^image\//.test(mime)) { try { thumb = await shrinkImage(f, 240, 0.7); } catch { /* no preview */ } }
  if (data.length * 0.75 > MAX_UP) throw new Error(`${name}: ${kb(data.length * 0.75)} — ${L2("too large", "حجم كبير")} (max ${MAX_UP / 1048576} MB)`);
  return api("POST", "/api/attachments", { owner, id, data, mime, thumb, title: name });
}
// the "Attach bills / receipts" field of entry forms, and sending its files once the entry (or its draft) exists
const ATTACH_FIELD = () => ({ k: "_files", type: "file", span: "spanall", multiple: 1, accept: "image/*,application/pdf,.pdf,.xlsx,.xls,.docx,.doc,.csv",
  l: L2("📎 Attach bills / receipts (PDF, photos…)", "📎 إرفاق الفواتير / الإيصالات (PDF، صور…)"),
  help: L2("The supplier's invoice, a receipt photo, a delivery note — kept with the entry (and in backups).", "فاتورة المورد أو صورة الإيصال أو إذن التسليم — تُحفظ مع القيد (وفي النسخ الاحتياطية).") });
async function attachFrom(f, r, entryId) {
  const inp = f && $("[name=_files]", f), files = inp ? [...inp.files] : []; if (!files.length || !r) return;
  const owner = r.pending ? "approval" : "entry", id = r.pending ? r.approval : (r.id || entryId); if (!id) return;
  let ok = 0; for (const file of files) { try { await uploadFile(owner, id, file); ok++; } catch (e) { fail(e); } }
  if (ok) toast(L2(`${ok} file(s) attached`, `تم إرفاق ${ok} ملف`));
}
