const demoWarn = kind => uiConfirm(L2(`Load the demo company${kind ? ` (${indName(kind)})` : ""}?\n\nThis fills these empty books with about six months of INVENTED data on every screen — customers, invoices, payroll, stock, loans and more. It is only for trying BeyondERP out: don't record real work on top of it.\n\nWhen you're done, erase it from Settings → System before you start with your real data.`,
  `تحميل الشركة التجريبية${kind ? ` (${indName(kind)})` : ""}؟\n\nسيملأ هذا الدفاتر الفارغة ببيانات وهمية لنحو ستة أشهر في كل الشاشات — عملاء وفواتير ورواتب ومخزون وقروض وغيرها. هي للتجربة فقط: لا تسجّل عملاً حقيقياً فوقها.\n\nعند الانتهاء امسحها من الإعدادات ← النظام قبل البدء ببياناتك الحقيقية.`));
const IND_NAMES = { general: ["General business", "نشاط عام"], interior: ["Interior design & finishing", "التصميم الداخلي والتشطيبات"],
  contracting: ["Contracting & construction", "المقاولات والإنشاءات"], development: ["Real-estate development", "التطوير العقاري"],
  sales: ["Trading & sales", "التجارة والمبيعات"], investment: ["Investment & holding", "الاستثمار والقابضة"],
  scaffolding: ["Scaffolding & equipment rental", "تأجير السقالات والمعدات"], healthcare: ["Clinics & medical centres", "العيادات والمراكز الطبية"],
  homecare: ["Home healthcare", "الرعاية الصحية المنزلية"] };
function indName(k) { const n = IND_NAMES[k]; return n ? L2(n[0], n[1]) : k; }
PAGES.industry = async (view) => {
  const d = await api("GET", "/api/industries");
  let dm = { empty: false }; try { dm = await api("GET", "/api/demo"); } catch { /* no permission */ }
  S.H.inddemo = async el => { const k = el.dataset.k;
    if (!dm.empty) return uiAlert(L2("These books already hold data, so a demo can't be loaded here — demo data only goes into empty books. To try it, use a new company (or back up, then erase the data in Settings → System).", "هذه الدفاتر بها بيانات، لذا لا يمكن تحميل بيانات تجريبية هنا — تُحمَّل في دفاتر فارغة فقط. للتجربة استخدم شركة جديدة (أو خذ نسخة احتياطية ثم امسح البيانات من الإعدادات ← النظام)."));
    if (!await demoWarn(k)) return;
    el.disabled = true; el.textContent = L2("Loading…", "جارٍ التحميل…");
    try { await api("POST", "/api/demo", { industry: k, confirmed: true }); await refreshBoot(); toast(L2("Demo loaded", "تم تحميل البيانات التجريبية")); location.hash = "#/dashboard"; }
    catch (e) { fail(e); el.disabled = false; } };
  const ed = can("settings.menus", "edit");
  S.H.indapply = async el => { const k = el.dataset.k, ty = d.types.find(x => x.key === k);
    if (!await uiConfirm(L2(`Set up this company as “${ty.name}”? Missing accounts are added, the sections it does not use are hidden (not deleted — Settings → Menus brings them back), and payroll gets its departments and pay items. Nothing is deleted.`, `ضبط الشركة كـ «${ty.name_ar}»؟ تُضاف الحسابات الناقصة وتُخفى الأقسام غير المستخدمة (لا تُحذف — الإعدادات ← القوائم تعيدها) وتُضبط أقسام الرواتب وبنودها. لا يُحذف شيء.`))) return;
    try { const r = await api("POST", "/api/industries/apply", { type: k }); toast(L2(`Done — ${r.accounts_added.length} account(s) added`, `تم — أُضيف ${r.accounts_added.length} حساب`)); await refreshBoot(); route(); } catch (e) { fail(e); } };
  view.innerHTML = `<div class="banner info">${L2("Pick what this company does. Each template switches on the sections it uses, adds the accounts it needs and sets payroll's departments, job titles, pay items and the crew calculator's work items. Download a ready Excel workbook for any type.", "اختر نشاط الشركة. كل قالب يفعّل الأقسام المستخدمة ويضيف الحسابات اللازمة ويضبط أقسام الرواتب والوظائف وبنود الأجر وبنود حاسبة الأطقم. ويمكن تحميل ملف إكسل جاهز لأي نشاط.")}</div>
    <div class="grid g2">${d.types.map(ty => `<div class="card"><h2>${esc(S.lang === "ar" ? ty.name_ar : ty.name)} ${d.current === ty.key ? `<span class="chip ok">${L2("current", "الحالي")}</span>` : ""}</h2>
      <ul>${ty.guide.map(g => `<li>${esc(g)}</li>`).join("")}</ul>
      <p class="muted">${L2("Business units are", "وحدات الأعمال")}: ${esc(ty.bu)} · ${L2("hidden", "مخفي")}: ${esc(ty.hide.join(", "))}${ty.accounts.length ? `<br>${L2("adds", "يضيف")}: ${ty.accounts.map(a => esc(a.code + " " + (S.lang === "ar" ? a.name_ar : a.name))).join(" · ")}` : ""}<br>${L2("crew work items", "بنود الأطقم")}: ${ty.work_items.map(w => esc(w.item + " (" + w.unit + ")")).join(" · ")}</p>
      <div class="row">${ed ? `<button class="btn ${d.current === ty.key ? "" : "pri"}" data-a="indapply" data-k="${ty.key}">${L2("Use for this company", "استخدم لهذه الشركة")}</button>` : ""}${S.boot.user.is_admin && (dm.empty || S.boot.user.is_super) ? `<button class="btn" data-a="inddemo" data-k="${ty.key}">▶ ${L2("Try its demo", "جرّب بياناته التجريبية")}</button>` : ""}<a class="btn" href="/api/templates/workbook?type=${ty.key}&lang=${S.lang}">⇩ ${L2("Excel template", "قالب إكسل")}</a></div></div>`).join("")}</div>`;
};

// files on the record pages (business unit, offer, loan, custody, rental, sale): appended under the page
[["bu", "bu", "business_units.units"], ["offer", "offer", "sales.offers"], ["po", "po", "purchasing.orders"], ["sub", "sub", "shop.subscriptions"], ["loan", "loan", "accounting.loans"], ["cust", "custody", "purchasing.custody"],
 ["rental", "rental", "rentals.contracts"], ["sale", "sale", "shop.orders"]].forEach(([page, owner, perm]) => {
  const orig = PAGES[page];
  PAGES[page] = async (view, parts, q) => {
    await orig(view, parts, q);
    if (!parts[1] || parts[1] === "new" || parts[2] || !view.isConnected || !$(".card", view) || $(".attbox", view)) return;   // no card = not found
    view.insertAdjacentHTML("beforeend", `<div class="card">${attBox(owner, parts[1], can(perm, "add"))}</div>`);
    mountAttach($(".attbox", view));
  };
});

// ================================================================== people, chat, notifications, AI assistant
/* BeyondERP — people, chat, notifications and the AI assistant (loaded after app.js, same helpers).
   Works the same in every edition: desktop/server (fetch), browser-only (the Python engine in the page) and the shared
   workspace (changes replicate like any other; chat between companies and the assistant's key live in Supabase). */

// ================================================================== shared helpers
const C2 = { people: null, peopleAt: 0, blobs: new Map(), last: 0 };
const me = () => S.boot.user;
const isSuper = () => !!(S.boot.user && S.boot.user.is_super);
async function loadPeople(force) {
  if (!force && C2.people && Date.now() - C2.peopleAt < 60000) return C2.people;
  try { C2.people = await api("GET", "/api/people"); C2.peopleAt = Date.now(); } catch { C2.people = C2.people || []; }
  return C2.people;
}
const personById = id => (C2.people || []).find(p => p.id === id) || { id, name: "?", username: "", avatar: "" };
const hue = s => { let h = 0; for (const c of String(s)) h = (h * 31 + c.charCodeAt(0)) % 360; return h; };
function avatar(p, size = 36) {
  const nm = (p && (p.name || p.username)) || "?";
  if (p && p.avatar) return `<img class="av" style="width:${size}px;height:${size}px" src="${esc(p.avatar)}" alt="">`;
  const ini = nm.trim().split(/\s+/).map(w => w[0]).join("").slice(0, 2).toUpperCase();
  return `<span class="av" style="width:${size}px;height:${size}px;font-size:${Math.round(size * .38)}px;background:hsl(${hue(nm)} 55% 46%)">${esc(ini)}</span>`;
}
const fmtTime = iso => { if (!iso) return ""; const d = new Date(String(iso).replace(" ", "T")); if (isNaN(d)) return String(iso);
  const today = new Date().toDateString() === d.toDateString();
  return today ? d.toLocaleTimeString(S.lang === "ar" ? "ar-EG" : undefined, { hour: "2-digit", minute: "2-digit" })
    : d.toLocaleString(S.lang === "ar" ? "ar-EG" : undefined, { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }); };
const dayOf = iso => String(iso || "").slice(0, 10);
const sizeTxt = n => n > 1048576 ? (n / 1048576).toFixed(1) + " MB" : n > 1024 ? Math.round(n / 1024) + " KB" : n + " B";
// text → safe HTML with links, @mentions and line breaks
function richText(s, mentionIds = []) {
  let h = esc(s || "");
  h = h.replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>');
  h = h.replace(/(^|[\s(])@([\w.\-\u0600-\u06FF]+)/g, (m, pre, nm) => `${pre}<b class="mention${(C2.people || []).some(p => p.username.toLowerCase() === nm.toLowerCase() && p.id === me().id) || /^(all|everyone|الكل)$/i.test(nm) ? " me" : ""}">@${nm}</b>`);
  return h.replace(/\n/g, "<br>");
}
// a protected file (chat attachment) as a link the browser can show: same request in every edition
async function apiBlobUrl(path) {
  if (C2.blobs.has(path)) return C2.blobs.get(path);
  let blob;
  if (STATIC) { const r = await window.__beyondFetch("GET", path, staticHeaders(), null); if (r.status >= 400) throw new Error("HTTP " + r.status); blob = new Blob([r.body], { type: r.ctype }); }
  else { const r = await fetch(path, { credentials: "same-origin", headers: { "X-Requested-With": "BeyondERP" } }); if (!r.ok) throw new Error("HTTP " + r.status); blob = await r.blob(); }
  const u = URL.createObjectURL(blob); C2.blobs.set(path, u); return u;
}
const b64ToBlob = (b64, mime) => { const bin = atob(b64), a = new Uint8Array(bin.length); for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i); return new Blob([a], { type: mime || "application/octet-stream" }); };
function saveBlob(blob, name) { const u = URL.createObjectURL(blob), a = document.createElement("a"); a.href = u; a.download = name || "file"; document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(u), 60000); }
// a picked / pasted file → {name, mime, size, data (base64), thumb (pictures)}
function readFile(file) {
  return new Promise((ok, bad) => {
    const fr = new FileReader();
    fr.onerror = () => bad(new Error("Could not read " + file.name));
    fr.onload = async () => {
      const url = String(fr.result), data = url.split(",")[1] || "";
      let thumb = "";
      if (/^image\/(png|jpe?g|gif|webp|bmp)/.test(file.type)) { try { thumb = await shrinkPic(url, 420, "image/jpeg", .78); } catch { thumb = ""; } }
      ok({ name: file.name || "pasted.png", mime: file.type || "application/octet-stream", size: file.size, data, thumb });
    };
    fr.readAsDataURL(file);
  });
}
function shrinkPic(src, max, type = "image/jpeg", q = .85, square = false) {
  return new Promise((ok, bad) => {
    const img = new Image();
    img.onload = () => {
      let sx = 0, sy = 0, sw = img.width, sh = img.height;
      if (square) { const m = Math.min(sw, sh); sx = (sw - m) / 2; sy = (sh - m) / 2; sw = sh = m; }
      const k = Math.min(1, max / Math.max(sw, sh)), w = Math.max(1, Math.round(sw * k)), h = Math.max(1, Math.round(sh * k));
      const c = document.createElement("canvas"); c.width = w; c.height = h;
      const g = c.getContext("2d"); if (type === "image/jpeg") { g.fillStyle = "#fff"; g.fillRect(0, 0, w, h); }
      g.drawImage(img, sx, sy, sw, sh, 0, 0, w, h); ok(c.toDataURL(type, q));
    };
    img.onerror = () => bad(new Error("not an image")); img.src = src;
  });
}
