// minimal, safe Markdown: paragraphs, **bold**, `code`, lists, headings, tables
function md(src) {
  const lines = String(src || "").split("\n"); let out = "", i = 0;
  const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, "<b>$1</b>").replace(/`([^`]+)`/g, "<code>$1</code>");
  while (i < lines.length) {
    const l = lines[i];
    if (/^```/.test(l)) { const buf = []; i++; while (i < lines.length && !/^```/.test(lines[i])) buf.push(lines[i++]); i++; out += `<pre>${esc(buf.join("\n"))}</pre>`; continue; }
    if (/^\s*\|.*\|\s*$/.test(l)) { const rows = []; while (i < lines.length && /^\s*\|.*\|\s*$/.test(lines[i])) rows.push(lines[i++]);
      const cells = r => r.trim().replace(/^\||\|$/g, "").split("|").map(c => c.trim());
      const body = rows.filter(r => !/^\s*\|[\s:\-|]+\|\s*$/.test(r));
      out += `<div class="tbl"><table><thead><tr>${cells(body[0] || "").map(c => `<th>${inline(c)}</th>`).join("")}</tr></thead><tbody>${body.slice(1).map(r => `<tr>${cells(r).map(c => `<td>${inline(c)}</td>`).join("")}</tr>`).join("")}</tbody></table></div>`; continue; }
    if (/^\s*([-*]|\d+\.)\s+/.test(l)) { const tag = /^\s*\d+\./.test(l) ? "ol" : "ul", buf = []; while (i < lines.length && /^\s*([-*]|\d+\.)\s+/.test(lines[i])) buf.push(lines[i++].replace(/^\s*([-*]|\d+\.)\s+/, ""));
      out += `<${tag}>${buf.map(x => `<li>${inline(x)}</li>`).join("")}</${tag}>`; continue; }
    const h = l.match(/^(#{1,4})\s+(.*)/); if (h) { out += `<h4>${inline(h[2])}</h4>`; i++; continue; }
    if (!l.trim()) { i++; continue; }
    const buf = []; while (i < lines.length && lines[i].trim() && !/^(```|\s*\||\s*([-*]|\d+\.)\s+|#{1,4}\s)/.test(lines[i])) buf.push(lines[i++]);
    out += `<p>${buf.map(inline).join("<br>")}</p>`;
  }
  return out;
}
function aiDraw() {
  const list = $("#ailist"); if (!list) return;
  const msgs = AI.thread.messages, results = {};
  msgs.forEach(m => { if (m.role === "user" && Array.isArray(m.content)) m.content.forEach(b => { if (b.type === "tool_result") results[b.tool_use_id] = b; }); });
  let h = "";
  if (!msgs.length) h = `<div class="ch-empty">${svg("spark")}<h2>${esc(L2("How can I help?", "كيف يمكنني المساعدة؟"))}</h2><div class="ai-sugg">${[
    L2("What is our cash position and what do we owe this month?", "ما وضع النقدية لدينا وما المستحق علينا هذا الشهر؟"),
    L2("Which projects made the most profit this year?", "ما أكثر المشروعات ربحاً هذا العام؟"),
    L2("List unpaid sales invoices older than 30 days", "اعرض فواتير المبيعات غير المحصلة الأقدم من ٣٠ يوماً"),
    L2("Summarise this month's expenses by type", "لخّص مصروفات هذا الشهر حسب النوع")].map(s => `<button class="btn" data-a="aisugg">${esc(s)}</button>`).join("")}</div></div>`;
  for (const m of msgs) {
    if (m.role === "user") {
      if (typeof m.content === "string") h += `<div class="ch-msg mine"><div class="ch-b"><div class="ch-bubble">${richText(m.content)}</div></div></div>`;
      else if (m.files) {   // a question with attachments: the files as chips / thumbnails, then the words
        const said = m.content.filter(b => b.type === "text" && !/^📎 /.test(b.text)).map(b => b.text).join("\n");
        h += `<div class="ch-msg mine"><div class="ch-b"><div class="ch-bubble"><div class="ch-files">${m.files.map(f => f.thumb ? `<span class="ch-img" title="${esc(f.name)}"><img src="${esc(f.thumb)}" alt="${esc(f.name)}"></span>` : `<span class="chip">${svg("file")} ${esc(f.name)} · ${esc(sizeTxt(f.size))}</span>`).join("")}</div>${said ? richText(said) : ""}</div></div></div>`;
      }
      continue;
    }
    for (const b of m.content || []) {
      if (b.type === "text" && b.text) h += `<div class="ch-msg ai-msg"><div class="ch-av">${aiAvatar(34)}</div><div class="ch-b"><div class="ch-bubble md">${md(b.text)}</div></div></div>`;
      if (b.type === "tool_use") {
        const r = results[b.id], inp = b.input || {};
        const label = b.name === "erp_find" ? L2("Looked for: ", "بحث عن: ") + (inp.query || "") : b.name === "erp_read" ? L2("Read ", "قرأ ") + (inp.path || "") : (inp.summary || inp.path || "");
        if (b.name === "erp_write") {
          h += reviewCard(b, inp, (AI.reviews || {})[b.id], r);
        } else {
          const bad = r && (r.is_error || /declined|رفض/.test(String(r.content)));
          h += `<div class="ai-act ${b.name === "erp_write" ? (bad ? "no" : "done") : ""}">${b.name === "erp_write" ? (bad ? "✕ " : "✓ ") : "· "}${esc(label)}</div>`;
        }
      }
    }
  }
  if (AI.busy) h += `<div class="ai-act"><i class="spin"></i> ${esc(L2("Working…", "جارٍ العمل…"))}</div>`;
  list.innerHTML = h; list.scrollTop = list.scrollHeight;
  S.H.aisugg = el => { const ta = $("#aitext"); ta.value = el.textContent; S.H.aisend(); };
}
// the change the assistant proposes: what the ERP's checks found, what it does to the numbers, and the entries it posts
function reviewCard(b, inp, rv, result) {
  const head = `<b>${esc(L2("Proposed change", "تعديل مقترح"))}</b><div>${esc(inp.summary || "")}</div>`;
  if (!rv || rv.checking) return `<div class="ai-act ask">${head}<div class="muted"><i class="spin"></i> ${esc(L2("Checking it against the books without saving anything…", "جارٍ فحصه على الدفاتر دون حفظ أي شيء…"))}</div></div>`;
  const checks = `<ul class="rv-checks">${rv.checks.map(c => `<li class="${c.ok ? "ok" : "bad"}">${c.ok ? "✓" : "✕"} ${esc(c.label)}${c.detail ? `<small>${esc(c.detail)}</small>` : ""}</li>`).join("")}</ul>`;
  const moved = rv.figures.filter(f => f.change);
  const figs = rv.figures.length ? `<div class="tbl"><table><thead><tr><th>${esc(L2("Figure", "البند"))}</th><th class="num">${esc(L2("Now", "الآن"))}</th><th class="num">${esc(L2("After", "بعد"))}</th><th class="num">${esc(L2("Change", "التغيير"))}</th></tr></thead><tbody>${
    (moved.length ? moved : rv.figures).map(f => `<tr><td>${esc(f.label)}</td><td class="num">${money(f.before)}</td><td class="num">${money(f.after)}</td><td class="num ${f.change < 0 ? "neg" : ""}">${f.change ? money(f.change) : "—"}</td></tr>`).join("")}</tbody></table></div>${moved.length ? "" : `<div class="muted">${esc(L2("No key figure changes.", "لا تتغير الأرقام الرئيسية."))}</div>`}` : "";
  const ents = rv.entries.length ? rv.entries.map(e => `<div class="rv-entry"><b>${esc(e.status === "new" ? L2("New entry", "قيد جديد") : e.status === "removed" ? L2("Entry removed", "قيد محذوف") : L2("Entry changed", "قيد معدّل"))}</b> ${esc([e.ref, e.date, e.memo].filter(Boolean).join(" · "))}
      ${e.lines.length ? `<div class="tbl"><table><tbody>${e.lines.map(l => `<tr><td>${esc(l.account)} ${esc(l.name)}</td><td class="num">${l.debit ? money(l.debit) : ""}</td><td class="num">${l.credit ? money(l.credit) : ""}</td></tr>`).join("")}</tbody></table></div>` : ""}</div>`).join("") : "";
  const tbls = rv.tables && rv.tables.length ? `<div class="muted">${esc(L2("Records:", "السجلات:"))} ${rv.tables.map(t => `${esc(t.table)} ${t.before}→${t.after}`).join(" · ")}</div>` : "";
  const state = result ? (rv.saved ? `<div class="chip ok">✓ ${esc(L2("Saved and posted after your review", "حُفظ ورُحّل بعد مراجعتك"))}</div>`
      : `<div class="chip ${rv.ok ? "" : "bad"}">${esc(rv.ok ? L2("Not saved", "لم يُحفظ") : L2("Blocked by the checks — nothing was saved", "أوقفته الفحوص — لم يُحفظ شيء"))}</div>`)
    : rv.ok ? `<div class="row"><button class="btn pri" data-a="aiok" data-id="${esc(b.id)}">${esc(L2("Save and post", "حفظ وترحيل"))}</button><button class="btn" data-a="aino" data-id="${esc(b.id)}">${esc(L2("Decline", "رفض"))}</button></div>` : "";
  return `<div class="ai-act ask ${rv.ok ? "" : "blocked"}">${head}<h5>${esc(L2("Checks (nothing saved yet)", "الفحوص (لم يُحفظ شيء بعد)"))}</h5>${checks}
    ${rv.ok ? `<h5>${esc(L2("Effect on the numbers", "الأثر على الأرقام"))}</h5>${figs}${ents ? `<h5>${esc(L2("Entries it will post", "القيود التي سيرحّلها"))}</h5>${ents}` : ""}${tbls}` : ""}
    <details><summary>${esc(L2("Request details", "تفاصيل الطلب"))}</summary><code>${esc(inp.method)} ${esc(inp.path)}</code><pre>${esc(inp.body_json || "")}</pre></details>${state}</div>`;
}
async function aiTool(b) {
  const inp = b.input || {};
  const cut = s => (s.length > 40000 ? s.slice(0, 40000) + "\n…(cut — narrow the request with filters)" : s);
  try {
    if (b.name === "erp_find") return { type: "tool_result", tool_use_id: b.id, content: JSON.stringify(await api("GET", "/api/ai/catalog?" + qs({ q: inp.query || "", limit: 40 }))) };
    if (b.name === "erp_read") { const r = await aiApi("GET", String(inp.path || "")); return { type: "tool_result", tool_use_id: b.id, content: cut(`HTTP ${r.status}\n${r.text}`), is_error: r.status >= 400 }; }
    if (b.name === "erp_write") {
      let body; try { body = JSON.parse(inp.body_json || "{}"); } catch { return { type: "tool_result", tool_use_id: b.id, content: "body_json is not valid JSON", is_error: true }; }
      if (!["POST", "PUT", "DELETE"].includes(inp.method)) return { type: "tool_result", tool_use_id: b.id, content: "method must be POST, PUT or DELETE", is_error: true };
      // 1. the ERP runs the change without saving it and checks the result
      AI.reviews = AI.reviews || {}; AI.reviews[b.id] = { checking: true }; aiDraw();
      let rv; try { rv = await api("POST", "/api/ai/preview", { method: inp.method, path: String(inp.path || ""), body }); }
      catch (e) { rv = { ok: false, checks: [{ key: "accepted", ok: false, label: L2("The ERP accepts the change", "يقبل النظام التعديل"), detail: e.message }], figures: [], entries: [], tables: [] }; }
      AI.reviews[b.id] = rv;
      const report = "Checks: " + rv.checks.map(c => `${c.ok ? "PASS" : "FAIL"} ${c.label}${c.detail ? " (" + c.detail + ")" : ""}`).join("; ") +
        (rv.figures.length ? "\nEffect: " + rv.figures.filter(f => f.change).map(f => `${f.label} ${f.before} -> ${f.after}`).join("; ") : "");
      if (!rv.ok) { aiDraw(); return { type: "tool_result", tool_use_id: b.id, content: "BLOCKED — nothing was saved.\n" + report + "\nFix the request and propose it again, or explain to the person.", is_error: true }; }
      // 2. the person reviews the checks and the effect on the numbers, and approves
      AI.busy = false; aiDraw();
      const okd = await new Promise(res => { AI.waiting = { ...(AI.waiting || {}), [b.id]: res }; });
      delete AI.waiting[b.id]; AI.busy = true;
      if (!okd) return { type: "tool_result", tool_use_id: b.id, content: "The person reviewed the checked change and declined it — nothing was saved. Do not retry it; ask what they want instead.\n" + report };
      // 3. saved and posted, carrying the review (the ERP refuses it if the books changed meanwhile)
      const r = await aiApi(inp.method, String(inp.path || ""), body, rv.review);
      AI.reviews[b.id].saved = r.status < 400;
      return { type: "tool_result", tool_use_id: b.id, content: cut(`Saved after review. HTTP ${r.status}\n${r.text}\n${report}`), is_error: r.status >= 400 };
    }
    return { type: "tool_result", tool_use_id: b.id, content: "Unknown tool", is_error: true };
  } catch (e) { return { type: "tool_result", tool_use_id: b.id, content: "Error: " + e.message, is_error: true }; }
}
async function aiSave() {
  const th = AI.thread, first = th.messages.find(m => m.role === "user" && (typeof m.content === "string" || m.files));
  const said = !first ? "" : typeof first.content === "string" ? first.content
    : first.content.filter(b => b.type === "text" && !/^📎 /.test(b.text)).map(b => b.text).join(" ") || first.files.map(f => f.name).join(", ");
  const title = (said || "Conversation").slice(0, 80);
  if (th.id) await api("PUT", "/api/ai/threads/" + th.id, { title, messages: th.messages });
  else {
    th.id = (await api("POST", "/api/ai/threads", { title, messages: th.messages })).id; history.replaceState(null, "", "#/assistant/" + th.id);
    const list = $(".ai .chl-list");   // show the new conversation in the list straight away
    if (list) { list.querySelector(".chl-note")?.remove(); list.querySelectorAll(".chl-item.on").forEach(x => x.classList.remove("on"));
      list.insertAdjacentHTML("afterbegin", `<a class="chl-item on" href="#/assistant/${th.id}"><span class="chl-ic">${svg("spark")}</span><span class="chl-t"><b>${esc(title)}</b><small>${esc(fmtTime(new Date().toISOString()))}</small></span><button class="lnk" data-a="aidel" data-id="${th.id}" title="${esc(L2("Delete", "حذف"))}">×</button></a>`); }
  }
}
// files attached to a question → content blocks every provider path understands: pictures and PDFs as they are,
// Excel / Word / PowerPoint and text files as their text; anything else by name only
const AI_TEXT = /\.(txt|csv|tsv|json|md|xml|html?|log|ya?ml|ini|sql|js|py|css)$/i;
async function aiBlocks(files) {
  const blocks = [];
  let size = 0;
  for (const f of files) {
    const label = `📎 ${f.name} (${sizeTxt(f.size)})`;
    if (/^image\/(png|jpe?g|gif|webp|bmp)/.test(f.mime)) {
      const url = await shrinkPic(`data:${f.mime};base64,${f.data}`, 1568, "image/jpeg", .85);   // the size providers read best
      const data = url.split(",")[1]; size += data.length;
      blocks.push({ type: "text", text: label }, { type: "image", source: { type: "base64", media_type: "image/jpeg", data } });
    } else if (f.mime === "application/pdf" || /\.pdf$/i.test(f.name)) {
      size += f.data.length;
      blocks.push({ type: "document", title: f.name, source: { type: "base64", media_type: "application/pdf", data: f.data } });
    } else if (/\.(xlsx|xlsm|docx|pptx)$/i.test(f.name)) {
      const r = await api("POST", "/api/ai/extract", { name: f.name, data: f.data });
      blocks.push({ type: "text", text: `${label}${r.cut ? " — only the first part fits" : ""}:\n${r.text}` });
    } else if (/^text\//.test(f.mime) || AI_TEXT.test(f.name)) {
      const txt = new TextDecoder().decode(Uint8Array.from(atob(f.data), c => c.charCodeAt(0)));
      blocks.push({ type: "text", text: `${label}:\n${txt.slice(0, 200000)}` });
    } else {
      blocks.push({ type: "text", text: `${label} — this kind of file cannot be read by the assistant; only its name was shared.` });
    }
  }
  if (size > 20 * 1048576) throw new Error(L2("The attachments are too large for one message (about 15 MB at most) — send fewer or smaller files", "المرفقات أكبر من المسموح لرسالة واحدة (حوالي ١٥ ميجابايت) — أرسل ملفات أقل أو أصغر"));
  return blocks;
}
async function aiSend(text, ta) {
  const files = AI.pending || [];
  if ((!text && !files.length) || AI.busy) return;
  const th = AI.thread;
  let content = text;
  if (files.length) {
    try { content = [...(await aiBlocks(files)), ...(text ? [{ type: "text", text }] : [])]; } catch (e) { fail(e); return; }
  }
  ta.value = ""; ta.style.height = "auto"; AI.pending = []; if (AI.drawPend) AI.drawPend();
  th.messages.push(files.length ? { role: "user", content, files: files.map(f => ({ name: f.name, size: f.size, thumb: f.thumb })) } : { role: "user", content });
  AI.busy = true; aiDraw();
  try {
    AI.ctx = AI.ctx && AI.ctx.at > Date.now() - 600000 ? AI.ctx : { ...(await api("GET", "/api/ai/context")), at: Date.now() };
    for (let step = 0; step < 24; step++) {
      const msg = await aiComplete(th.messages, AI.ctx);
      th.messages.push({ role: "assistant", content: msg.content });   // kept exactly as returned (thinking blocks included)
      aiDraw();
      if (msg.stop_reason === "refusal") { th.messages.push({ role: "user", content: L2("(The request was declined by the AI provider's safety checks.)", "(رفضت فحوص الأمان لدى مزوّد الذكاء الاصطناعي هذا الطلب.)") }); break; }
      if (msg.stop_reason !== "tool_use") break;
      const results = [];
      for (const b of msg.content.filter(x => x.type === "tool_use")) results.push(await aiTool(b));
      th.messages.push({ role: "user", content: results });
      aiDraw(); await aiSave();
    }
  } catch (e) { fail(e); th.messages.push({ role: "assistant", content: [{ type: "text", text: "⚠️ " + e.message }] }); }
  finally { AI.busy = false; aiDraw(); try { await aiSave(); } catch { /* kept on screen */ } loadAiPolicy(); }
}

