      const keys = ((em.find(([g]) => g === tg) || [, []])[1]).map(i => i[0]).filter(x => x !== k);
      if (t.pos === "into") keys.push(k); else keys.splice(keys.indexOf(t.k) + (t.pos === "after" ? 1 : 0), 0, k);
